ACTIVATION_X_MIN = 5.0
AGENT_MASS = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0
INTERNAL_WALL_X = 9.0  # Position of the critical internal wall
INTERNAL_WALL_TOLERANCE = 0.3  # Distance to consider wall proximity

def _control_cfg(_sandbox):
