def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "unlock_streak": 0,
            "escape_y": 1.5  # Target y for escape to avoid internal wall
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    # Check for wall avoidance using position (whiskers may be unreliable)
    wall_proximity = 0.0
    if x + 0.2 >= INTERNAL_WALL_X - INTERNAL_WALL_TOLERANCE and x <= INTERNAL_WALL_X + 0.2:
        wall_proximity = 1.0  # Apply upward force to avoid collision

    # Navigation logic
    if state["phase"] == "APPROACH":
        # Apply forward force with wall avoidance
        fx = 15.0 if x < 5.0 else 10.0 * (7.0 - x) - 5.0 * vxd
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp + (5.0 if wall_proximity else 0.0)
        # Check for activation zone entry
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["unlock_streak"] = 0
    elif state["phase"] == "UNLOCK":
        # Apply strong backward force to unlock
        fx_cmd = cfg["bfx"] - 1.0  # -35.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp + (5.0 if wall_proximity else 0.0)
        # Check if unlock condition is met (5 consecutive steps)
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        if fx_cmd < cfg["bfx"] and spd < cfg["bspd"]:
            state["unlock_streak"] += 1
        else:
            state["unlock_streak"] = 0
        fx, fy = fx_cmd, fy_cmd
        if state["unlock_streak"] >= 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force with wall avoidance
        fx = 15.0
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp + (5.0 if wall_proximity else 0.0)
        # Check if in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Apply minimal force to maintain position
        fx, fy = 0.0, w_comp

    # Apply forces
    sandbox.apply_agent_force(fx, fy)

